const subName=(s,id)=>s.submissions.find(x=>x.id===id)?.version||short(id);
const teamName=(s,id)=>s.competition?.entries.find(x=>x.team_id===id)?.name||short(id);
const form=(id,body)=>`<form id="${id}" class="real-form">${body}${errors()}</form>`;
const stats=items=>`<div class="stats-grid">${items.map(([label,value,ico,foot=''])=>`<div class="stat"><p class="stat-label">${esc(label)}</p><div class="stat-value">${esc(value)}</div><p class="stat-foot">${esc(foot)}</p></div>`).join('')}</div>`;
const authTabs=route=>l10n`<nav class="real-auth-tabs"><a class="${route==='login'?'active':''}" href="#/login">Đăng nhập</a><a class="${route==='register'?'active':''}" href="#/register">Đăng ký cá nhân</a></nav>`;
export function authPage(s) {
  if(s.route==='login') return authFrame(l10n`<h2>Đăng nhập</h2><p>Dùng email trường và mật khẩu. Khách và BTC dùng username đã được cấp.</p>${authTabs('login')}${form('login-form',field('Email / username','username','required autocomplete="username" maxlength="120"')+password(tr('Mật khẩu'),'login-password')+submit(tr('Đăng nhập')))}<a class="text-link" href="#/recover">Quên mật khẩu?</a>${note(tr('Chưa có tài khoản? Đăng ký bằng email trường, rồi tạo hoặc vào đội bốn người.'))}<a href="#/home" class="text-link">Về trang chủ</a>`);
  if(s.route==='recover') return authFrame(l10n`<h2>Cấp lại mật khẩu</h2><p>Gửi mã tài khoản và email đội trưởng đã đăng ký để ban tổ chức kiểm tra.</p>${s.recoverySent?note(tr('Đã ghi nhận yêu cầu. Nếu thông tin khớp, ban tổ chức sẽ kiểm tra và cấp mật khẩu tạm qua kênh của giải.')):form('recovery-form',field(tr('Tên đăng nhập'),'username','required maxlength="30"')+field(tr('Email đội trưởng'),'email','required maxlength="120"','email')+submit(tr('Gửi yêu cầu')))}<a href="#/login" class="text-link">Quay lại đăng nhập ${icon('arrow')}</a>`);
  if(s.route==='change-password') return authFrame(`<h2>${s.user?.must_change_password?tr('Đổi mật khẩu tạm'):tr('Đổi mật khẩu')}</h2><p>${s.user?.must_change_password?tr('Hoàn tất bước này để vào trang quản lý đội.'):tr('Sau khi đổi, các phiên cũ sẽ được đăng xuất.')}</p>${form('password-form',password(tr('Mật khẩu hiện tại / mật khẩu tạm'),'current-password')+password(tr('Mật khẩu mới (8–128 ký tự)'),'new-password','new-password')+password(tr('Nhập lại mật khẩu mới'),'confirm-password','new-password')+submit(tr('Lưu mật khẩu mới')))}${s.user?.must_change_password?button(tr('Đăng xuất'),'logout'):link('home',tr('Về tổng quan'))}`);
  if(s.registrationReceipt) return authFrame(l10n`<h2>Đã gửi hồ sơ đăng ký</h2>${note(tr('Ban tổ chức sẽ duyệt hồ sơ và cấp tài khoản cho đội.'))}<dl class="detail-list"><div><dt>Mã hồ sơ</dt><dd class="mono">${esc(s.registrationReceipt.id)}</dd></div><div><dt>Trạng thái</dt><dd>${badge('pending',tr('Chờ duyệt'))}</dd></div></dl>${link('login',tr('Về đăng nhập'),'primary')}`);
  const d=s.registrationDraft||{team:'',email:'',phone:'',members:Array.from({length:3},()=>({name:'',student_id:''}))};
  return authFrame(l10n`<h2>Đăng ký đội</h2><p>Đăng ký 3–4 thành viên. Ban tổ chức duyệt hồ sơ và cấp tài khoản cho đội.</p>${authTabs('register')}${form('registration-form',field(tr('Tên đội'),'team','required minlength="2" maxlength="40"','text',d.team)+l10n`<div class="form-grid">${field(tr('Email đội trưởng'),'email','required maxlength="120"','email',d.email)}${field(tr('Số điện thoại (tùy chọn)'),'phone','maxlength="20"','tel',d.phone)}</div><div class="section-head"><h3>Thành viên <span class="muted">${d.members.length}/4</span></h3>${d.members.length<4?button(tr('Thêm người thứ 4'),'add-member'):button(tr('Bỏ người thứ 4'),'remove-member')}</div>`+d.members.map((m,i)=>`<fieldset class="member-field"><legend>${i===0?tr('Đội trưởng'):tr('Thành viên ')+(i+1)}</legend><div class="form-grid">${field(tr('Họ và tên'),`name-${i}`,'required minlength="2" maxlength="60"','text',m.name)}${field(tr('Mã sinh viên'),`student-${i}`,'required pattern="[A-Za-z0-9]{6,15}"','text',m.student_id)}</div></fieldset>`).join('')+l10n`<label class="check-field"><input type="checkbox" name="confirmed" required>Đội xác nhận thông tin chính xác và đồng ý luật thi đấu OTTv2.</label>`+submit(tr('Gửi hồ sơ đăng ký')))}<a href="#/home" class="text-link">Về trang chủ</a>`);
}

export function compCards(s) {
  const events=s.importedEvents||[],finals=s.competitionArchived?[]:(s.finals||[]),admin=s.user?.role==='admin';
  const children=new Set(finals.flatMap(f=>Object.values(f.slots||{}).map(x=>x.competition_id)));
  const entries=finals.map(f=>{const event=events.find(e=>(e.finals||[]).some(x=>x.id===f.id));return {status:f.status,created:event?.imported_ms||f.created_ms,html:finalCard(f,event,admin)};});
  const imported=s.competitionArchived?[]:events.flatMap(e=>e.competitions.map(c=>({...c,event:e,status:'completed',config:{format:c.format,max_teams:c.teams}})));
  const items=[...(s.competitions||[]).filter(c=>!!c.archived_ms===!!s.competitionArchived),...imported];
  const seen=new Set();
  for(const c of items){
    if(children.has(c.id)||seen.has(c.id))continue;seen.add(c.id);
    entries.push({status:c.status,created:c.event?.imported_ms||c.created_ms,html:l10n`<article class="real-card" data-key="competition-${c.id}"><div class="section-head">${badge(c.archived_ms?'aborted':c.status,c.archived_ms?tr('Đã lưu trữ'):undefined)}<span class="muted">${c.event?'':timeLabel(competitionProfile(c))}</span></div><h3>${esc(c.title)}</h3>${c.config.ruleset?badge('attention','Ruleset add-on'):''}<p>${c.config.format==='elo'?tr('Ladder Elo + vòng tròn'):c.config.format==='swiss'?'Swiss · '+(c.config.rounds||tr('Tự tính'))+tr(' vòng'):tr('Vòng tròn hai lượt')} · Tối đa ${c.config.max_teams} đội</p>${c.event?`<p class="muted">${tr('Nạp từ hub LAN lúc ')}${date(c.event.imported_ms)}</p>`:''}<div class="table-actions">${link('competitions/'+c.id,tr('Mở giải đấu'),'small')}${admin?(c.event?button(tr('Ẩn'),'hide-imported',`data-id="${esc(c.event.id)}"`,'small danger-button'):competitionTools(c)):''}</div></article>`});
  }
  const active=x=>['open','running','groups','knockout'].includes(x.status)?1:0;
  entries.sort((a,b)=>active(b)-active(a)||(b.created||0)-(a.created||0));
  return entries.length?`<div class="real-card-grid">${entries.map(e=>e.html).join('')}</div>`:empty(s.competitionArchived?tr('Chưa có giải đã xóa'):tr('Chưa có giải đấu'),tr('Các giải sẽ xuất hiện tại đây khi ban tổ chức tạo giải.'));
}
function home(s) {
  if(s.user?.role==='admin')return adminDashboard(s);
  if(s.user&&!s.user.team_id&&!s.team)return accountTeamPage(s);
  if(!s.user) return l10n`${head('UET Bot Arena',tr('Nền tảng thi đấu bot OTTv2 dành cho sinh viên.'),link('register',tr('Đăng ký đội'),'primary'))}<section class="guest-intro"><div><h2>Thi đấu bot Oẳn Tù Tì</h2><p>Các đội nộp bot Python, C hoặc C++ để thi đấu theo luật OTTv2 (mặc định bàn 9×9; BTC có thể đổi luật theo giải). Bạn có thể xem lịch, bảng xếp hạng và trận đấu mà không cần tài khoản.</p></div><div class="page-actions">${link('live',tr('Xem trận không cần đăng nhập'),'primary')}${link('guide',tr('Luật chơi & hướng dẫn'))}</div></section>${recentMatchPanel(s.recentMatch)}${panel(tr('Giải đấu công khai'),compCards(s),link('schedule',tr('Xem lịch đấu'),'small'))}<ol class="onboarding">${[[tr('Xác minh tài khoản'),tr('Xác minh email trường, rồi lập hoặc vào đội bốn người.')],[tr('Nộp và kiểm tra bot'),tr('Dùng repo mẫu Python, C hoặc C++; push lên GitHub để hub tự kiểm tra, hoặc dán code để thử nhanh.')],[tr('Tham gia giải'),tr('Bản Đạt mới nhất vào ladder; hub khóa bot tại hạn để xếp hạng chính thức.')]].map(([title,text],i)=>`<li><span>${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol>`;
  const admin=s.user.role==='admin', d=s.dashboard||{};
  return l10n`${head(tr('Tổng quan'),s.team?.name?tr('Đội ')+s.team.name:tr('Thông tin giải đấu và hoạt động của đội.'),admin?link('admin',tr('Duyệt đội thi'),'primary'):link('submissions',tr('Nộp phiên bản bot'),'primary'))}${admin?stats([[tr('ĐỘI THAM GIA'),d.teams||0,'users'],[tr('HỒ SƠ CHỜ DUYỆT'),d.pending_registrations||0,'file'],[tr('GIẢI ĐẤU'),d.competitions||0,'trophy'],[tr('Tác vụ đang chạy'),d.active_jobs||0,'code']]):stats([[tr('Phiên bản bot'),d.counts?.submissions||0,'upload'],[tr('Kiểm tra'),d.counts?.benchmarks||0,'code'],[tr('Trận luyện tập'),d.counts?.matches||0,'play'],[tr('Tác vụ đang chạy'),d.counts?.active_jobs||0,'clock']])}${teamCompetitions(s)}<div class="section-head"><div><h2>Giải đấu</h2></div>${link('competitions',tr('Xem tất cả'))}</div>${compCards(s)}${!admin?panel(tr('Hoạt động gần đây'),jobTable(s,s.jobs.slice(0,5))):note(tr('Duyệt hồ sơ đội trước, sau đó mở giải để các đội chọn bot đã benchmark. Chốt lịch khi đủ đội và bắt đầu giải.'))}`;
}
export function jobTable(s,jobs) {
  return jobs.length?table([tr('Tác vụ'),tr('Loại'),tr('Trạng thái'),tr('Tạo lúc'),''],jobs.map(j=>`<tr data-key="job-${j.id}"><td class="mono">${short(j.id)}</td><td>${j.kind==='benchmark'?tr('Kiểm tra'):tr('Luyện tập')}</td><td>${badge(j.status)}</td><td>${date(j.created_unix_ms)}</td><td>${link('jobs/'+j.id,tr('Chi tiết'),'small')}</td></tr>`)):empty(tr('Chưa có tác vụ'),tr('Kết quả kiểm tra và luyện tập sẽ xuất hiện tại đây.'));
}
function submissions(s) {
  if(!s.platform?.team_zip_upload)return githubPage(s);
  return head(tr('Nạp file ZIP'),tr('Hub chung kết không có GitHub; nén thư mục bot như repo mẫu.'))+panel(tr('Phiên bản bot'),form('zip-form',field(tr('Tên phiên bản'),'version','required pattern="v?[0-9]+\\.[0-9]+\\.[0-9]+(-[A-Za-z0-9.-]+)?"','text','v1.0.0')+`<label class="field"><span>${tr('Ngôn ngữ')}</span>${select('runtime',[['cpp17','C++17'],['c11','C11'],['python3','Python 3']])}</label>`+field(tr('File ZIP'),'source','required accept=".zip,application/zip"','file')+note(tr('Mỗi bài tự kiểm 72 mẫu; tối đa 30 bài nguồn mỗi giờ.'))+submit(tr('Nạp và kiểm tra'))))+panel(tr('Lịch sử kiểm tra'),jobTable(s,s.jobs.filter(j=>j.kind==='benchmark')));
}

function benchmark(s) {
  return `${head(tr('Kiểm tra bot'),tr('24 trạng thái × 3 lần, tổng 72 mẫu. Mỗi mẫu có tối đa 0,5 giây riêng, không dùng đồng hồ thi đấu.'))}${panel(tr('Chạy kiểm tra'),s.submissions.length?form('benchmark-form',l10n`<div class="form-grid"><label class="field"><span>Phiên bản</span>${select('submission_id',s.submissions.map(x=>[x.id,submissionLabel(x)+' · '+runtimeLabel(x.runtime)+' · SDK v'+(x.protocol_version||2)]),s.selectedSubmission)}</label>${s.benchmarkCompetition?note(tr('Ghim nền tảng, bộ luật và binary theo giải: ')+s.competition?.title):''}</div>`+botRulesetField(s,[s.selectedSubmission||s.submissions[0]?.id],s.selectedRuleset)+note(tr('Đạt kiểm tra chưa bảo đảm bot đủ quỹ giờ cho cả ván; hãy luyện tập với thời gian thi đấu.'))+submit(tr('Kiểm tra trên máy chấm'))):empty(tr('Cần nộp bot trước'),tr('Nộp bot qua GitHub tại trang Bot.')))}${panel(tr('Lịch sử kiểm tra'),jobTable(s,s.jobs.filter(j=>j.kind==='benchmark')))}`;
}
function practice(s) {
  const options=s.submissions.map(x=>[x.id,submissionLabel(x)+' · '+runtimeLabel(x.runtime)+' · SDK v'+(x.protocol_version||2)]),opponents=[...options,...(s.sampleBots||[]).filter(b=>b.protocol_version===2).map(b=>['sample:'+b.id,tr('Bot mẫu BTC · ')+b.name])];
  return `<div id="sample-practice">${head(tr('Luyện tập'),tr('Đấu giữa hai phiên bản của đội hoặc bot mẫu BTC; kết quả không tính vào giải.'))}${panel(tr('Trận luyện tập mới'),options.length?form('practice-form',l10n`<div class="form-grid"><label class="field"><span>Bot của đội</span>${select('red_submission_id',options)}</label><label class="field"><span>Đối thủ (phiên bản khác của đội hoặc bot mẫu BTC)</span>${select('blue_submission_id',opponents)}</label><label class="field"><span>Bot của đội cầm quân</span>${select('team_side',[['red',tr('Đỏ (đi trước)')],['blue',tr('Xanh')]])}</label></div>${timeField()}${note(tr('Mỗi bot có quỹ riêng cho cả trận. Chỉ chạy đồng hồ khi đến lượt; không cộng giây sau nước đi.'))}${botRulesetField(s,[s.submissions[0]?.id,s.submissions[0]?.id])}<label class="check-field"><input type="checkbox" name="delegate" required>Đội đồng ý: khi một bot hết quỹ giờ, server thay mặt đối thủ tuyên bố thua sau khoảng chờ 3 giây.</label>`+submit(tr('Tạo trận luyện tập'))):empty(tr('Chưa có bot'),tr('Nộp source Python, C hoặc C++ để thử một trận đầu tiên.')))}${panel(tr('Các trận của đội'),jobTable(s,s.jobs.filter(j=>j.kind==='match')))}</div>`;
}
function fixturesTable(s,rows) {
  return rows.length?table([tr('Trận'),tr('Đỏ · Đi trước'),tr('Xanh'),tr('Trạng thái / kết quả'),''],rows.map(f=>`<tr><td>#${f.ordinal}</td><td>${esc(teamName(s,f.red_team_id))}</td><td>${esc(teamName(s,f.blue_team_id))}</td><td>${badge(f.status)}${f.result?`<div class="muted">${esc(resultLabel(f.result,side=>teamName(s,f[side+'_team_id'])))}</div>`:''}</td><td>${link(`${f.status==='completed'?'replay':'arena'}/${f.competition_id}/${f.id}`,f.status==='completed'?'Replay':tr('Xem trận'),'small')}${s.user?.role==='admin'&&f.status==='attention'?button(tr('Xem lỗi'),'diagnostic',`data-fixture="${f.id}"`,'small'):''}</td></tr>`)):empty(tr('Chưa có lịch đấu'),tr('Lịch đấu được tạo sau khi ban tổ chức chốt bot.'));
}
function competitionSelect(s) {
  return l10n`<div class="filters"><label class="field"><span>Giải đang xem</span>${select('competition-select',[['',tr('Chọn giải đấu')],...s.competitions.map(c=>[c.id,c.title])],s.competition?.id||'',false)}</label>${s.competition?link('competitions/'+s.competition.id,tr('Thông tin giải'),'small'):''}</div>`;
}
function competition(s) {
  const parent=(s.finals||[]).find(f=>Object.values(f.slots||{}).some(x=>x.competition_id===s.competition?.id));
  const back=parent?`<a class="text-link" href="#/finals/${esc(parent.id)}">← ${esc(parent.name)}</a>`:'';
  return back+competitionBody(s.importedEvent?{...s,user:null,importedView:true}:s);
}
function competitionBody(s) {
  if(!s.competition) return empty(tr('Chưa chọn giải'),tr('Chọn một giải đấu từ danh sách.'));
  const c=s.competition,admin=s.user?.role==='admin',own=c.entries.find(e=>e.team_id===s.user?.team_id);
  const actions=admin&&!c.archived_ms?{draft:[['open',tr('Mở đăng ký')]],open:[['lock',tr('Chốt bot và tạo lịch')]],locked:[['start',tr('Bắt đầu giải')]],running:[['pause',tr('Tạm dừng ghép trận')]],paused:[['start',tr('Tiếp tục giải')]]}[c.status]||[]:[];
  if(c.config.format==='elo')return eloCompetition(s,actions.map(([a,l])=>button(l,'competition-action',`data-command="${a}"`,'primary')).join('')+(admin?competitionTools(c):''));
  const qualified=s.jobs.filter(j=>s.submissions.find(x=>x.id===j.submission_ids?.[0])?.channel!=='practice'&&j.kind==='benchmark'&&j.status==='completed'&&j.benchmark_summary?.passed&&j.benchmark_summary.samples===72&&(j.profile.id.startsWith('ottv2-check-500ms-v1')||j.profile.id===c.config.profile.id)&&(!c.config.image_id||j.image_id===c.config.image_id)&&(j.ruleset?.hash||'')===(c.config.ruleset?.hash||'')&&(j.basic_rules?.hash||'')===(c.config.basic_rules?.hash||''));
  return l10n`${head(c.title,(c.config.format==='swiss'?'Swiss · '+(c.config.current_round||0)+'/'+(c.config.rounds||tr('tự tính'))+tr(' vòng · Buchholz'):tr('Vòng tròn hai lượt'))+(c.config.scoring?.win===1?tr(' · Thắng 1đ · Hòa ½đ · Thua 0đ'):tr(' · Thắng 3đ · Hòa 1đ · Thua 0đ')),actions.map(([a,l])=>button(l,'competition-action',`data-command="${a}"`,'primary')).join('')+(admin?competitionTools(c):''))}${s.importedEvent?importedBanner(s.importedEvent):''}<div class="competition-summary">${badge(c.archived_ms?"aborted":c.status,c.archived_ms?tr("Đã lưu trữ"):"")}<span>${timeLabel(competitionProfile(c))}</span><span>${c.entries.length}/${c.config.max_teams} đội</span><span>${c.fixture_counts.completed} trận hoàn tất</span>${c.fixture_counts.attention?badge('attention',c.fixture_counts.attention+tr(' trận cần xử lý')):''}</div>${c.config.ruleset?note('Ruleset add-on · '+c.config.ruleset.definition.name+' · v'+c.config.ruleset.version+' · '+c.config.ruleset.hash.slice(0,12))+(s.user?link('rulesets/'+c.config.ruleset.id,tr('Chi tiết luật & hướng dẫn bot'),'small'):''):''}${note(rulesLabel(c.config))}${note(policyLabel(c.config))}${c.config.pairing_error?l10n`<div class="form-error visible">Không ghép được vòng Swiss tiếp theo: ${esc(c.config.pairing_error)}. Giải đã tạm dừng; BTC xử lý rồi bấm Bắt đầu để ghép lại.</div>`:''}${!s.user&&!s.importedView?note(tr('Bạn đang xem với tư cách khách. Đăng nhập tài khoản đội để chọn bot dự giải.'))+link('login',tr('Đăng nhập đội'),'small'):''}${s.user?.team_id&&c.status==='open'&&s.personal?.team?.captain_id===s.user.id?panel(own?tr('Phiên bản đội đang chọn: ')+own.version:tr('Chọn bot dự giải'),qualified.length?form('entry-form',l10n`<label class="field"><span>Bản kiểm tra Đạt của đội</span>${select('qualified',qualified.map(j=>[j.submission_ids[0]+':'+j.id,subName(s,j.submission_ids[0])+' · '+short(j.id)+' · '+date(j.created_unix_ms)]))}</label><label class="check-field"><input name="delegate" type="checkbox" required>Đội đồng ý: khi một bot hết quỹ giờ, server thay mặt đối thủ tuyên bố thua sau khoảng chờ 3 giây.</label>`+submit(own?tr('Thay bot dự giải'):tr('Đăng ký bot dự giải'))+(own?button(tr('Rút bot khỏi giải'),'withdraw-entry'):'')+note(tr('Bạn có thể thay hoặc rút bot trước khi admin chốt. Sau khi chốt, mọi trận dùng đúng binary đã kiểm tra.'))):empty(tr('Cần bản kiểm tra Đạt theo cấu hình giải'),tr('Chạy kiểm tra 72 mẫu, mỗi mẫu tối đa 0,5 giây, rồi quay lại chọn bot.'))+link('benchmark?competition='+c.id+(c.config.ruleset?'&ruleset='+c.config.ruleset.id:''),tr('Đến kiểm tra'),'primary')):''}${admin&&['draft','open'].includes(c.status)&&!c.archived_ms?panel(tr('Thêm đội'),form('admin-entry-form',`<label class="field"><span>${tr('Đội')}</span>${select('team_id',(s.entryTeams||[]).map(t=>[t.id,t.name]))}</label>`+note(tr('Dùng bản Đạt mới nhất hợp với luật và cấu hình máy chấm của giải.'))+submit(tr('Thêm đội')))):''}${panel(tr('Đội dự giải'),c.entries.length?table([tr('Đội'),tr('Phiên bản'),tr('Chọn lúc'),''],c.entries.map(e=>`<tr><td><strong>${esc(e.name)}</strong></td><td>${esc(e.version)}</td><td>${date(e.accepted_ms)}</td><td>${admin&&c.status==='open'?button(tr('Loại khỏi giải'),'remove-entry',`data-team="${e.team_id}"`,'small'):''}</td></tr>`)):empty(tr('Chưa có đội đăng ký bot')))}${panel(tr('Lịch đấu'),fixturesTable(s,s.fixtures),link('standings?competition='+c.id,tr('Bảng xếp hạng'),'small'))}`;
}
function competitions(s) {
  if(s.ids[0]) return competition(s);
  const create=s.user?.role==='admin'?panel(tr('Tạo giải mới'),form('competition-form',field(tr('Tên giải'),'title','required minlength="3" maxlength="100"')+`<p data-elo-time>${tr('Ladder và xếp hạng chính thức: 10 giây mỗi bot')}</p><div class="form-grid"><div data-competition-time hidden>${timeField()}</div>${field(tr('Số đội tối đa'),'max_teams','required min="2" max="4096"','number','16')}</div>`+tournamentOptions()+rulesetField(s,s.selectedRuleset||'',true)+note(s.platform?.team_zip_upload?tr('Vòng tròn LAN: mỗi cặp 2 ván đổi màu; thắng 1, hòa ½, thua 0. Xếp theo điểm, đối đầu, số ván thắng; vẫn bằng thì đồng hạng.'):tr('Mỗi cặp đấu 2 ván đổi màu. Thắng 3 điểm, hòa 1, thua 0. Vòng tròn: điểm → đối đầu → số ván thắng → đồng hạng; Swiss: bằng điểm xét Buchholz. Thời gian chỉ sửa được khi giải còn là bản nháp và chưa có đội chọn bot.'))+submit(tr('Tạo bản nháp')))):'';
  return `${head(tr('Giải đấu'),tr('Chọn giải để xem thông tin, đăng ký bot và theo dõi kết quả.'),resultsTools(s))}${create}${s.user?.role==='admin'?l10n`<label class="check-field"><input type="checkbox" name="competition-archived" ${s.competitionArchived?'checked':''}>Xem giải đã lưu trữ</label>`:''}${compCards(s)}`;
}
function rankingLookup(s){
  if(s.user||!s.competition||(s.standings?.total||0)<=100)return '';
  const r=s.rankingLookup;
  return panel(tr('Tra đội'),note(tr('Bảng chính hiển thị 100 đội đầu. Chọn đội để xem thứ hạng của bất kỳ đội nào.'))+form('standings-lookup',l10n`<label class="field"><span>Đội</span>${select('team_id',s.competition.entries.map(e=>[e.team_id,e.name]))}</label>`+submit(tr('Tra thứ hạng')))+(r?l10n`<p><strong>${esc(r.name)}</strong> · Hạng ${esc(r.rank??'—')} · ${r.points!==undefined?tr('Điểm ')+esc(r.points):'Elo '+esc(r.rating?.toFixed(2))} · ${esc(r.played)} ván</p>`:''));
}
function queuePage(s){
  const q=s.queue;if(!q)return head(tr('Tình trạng chấm'))+empty(tr('Đang cập nhật hàng đợi'));
  return '<div id="queue-page">'+head(tr('Tình trạng chấm'),tr('Tiến độ chung của giải và các lượt kiểm tra bot.'))+stats([[tr('Đang chờ kiểm tra'),q.waiting.checks,'clock'],[tr('Đấu chính thức đang chờ'),q.waiting.official,'trophy'],[tr('Ladder / luyện tập chờ'),q.waiting.practice,'code'],[tr('Đang xử lý'),q.running,'bolt']])+note(tr('Các yêu cầu đang xếp hàng sẽ được nhận theo thứ tự ưu tiên. Xem vị trí và tiến độ bài của bạn ở trang Nộp bài.'))+l10n`<p class="muted">Cập nhật ${date(q.generated_ms)}</p></div>`;
}
function standings(s) {
  if(s.competition?.config?.format==='elo')return head(tr('Xếp hạng'),s.competition.title,!s.user?l10n`<a class="btn small" href="/snapshots/standings/${esc(s.competition.id)}.csv">Xuất CSV</a>`:'')+competitionSelect(s)+rankingLookup(s)+eloStandings(s);
  return `${head(tr('Bảng xếp hạng.'),s.competition?.config?.scoring?.win===1?tr('Điểm → đối đầu → số ván thắng → đồng hạng · Thắng 1đ, hòa ½đ, thua 0đ.'):tr('Vòng tròn: điểm → đối đầu → số ván thắng → đồng hạng · Swiss: điểm → Buchholz.'),s.standings?.items.length?button(tr('Xuất CSV'),'export-standings'):'' )}${competitionSelect(s)}${rankingLookup(s)}${s.competition?panel(s.competition.title,(s.standings?.provisional?note(tr('Bảng tạm thời: giải còn trận chưa hoàn tất. Trận lỗi hạ tầng không được tính thành hòa hoặc thua.')):'')+(s.standings?.items.length?standingsChart({...s.standings,items:s.standings.items.filter(t=>!t.is_guest)},s.user?.team_id)+(s.standings.items.some(t=>t.is_guest)?note(tr('Đội khách không được xếp hạng: ')+s.standings.items.filter(t=>t.is_guest).map(t=>t.name).join(', ')):''):empty(tr('Chưa có đội dự giải')))):empty(tr('Chưa có bảng xếp hạng'),tr('Chọn một giải đấu để xem kết quả. Không dùng trận luyện tập để tính hạng.'))}`;
}
function schedule(s,live=false) {
  const rows=live?s.fixtures.filter(f=>f.status==='queued'):s.fixtures;
  return `${head(live?tr('Trực tiếp'):tr('Lịch thi đấu'),live?tr('Mở trận để theo dõi bàn cờ cập nhật tại chỗ.'):tr('Mỗi cặp đội đấu hai lượt và đổi màu.'),button(tr('Làm mới'),'refresh'))}${competitionSelect(s)}${s.competition?panel(s.competition.title,(s.historyTotal>s.fixtures.length?note(tr('Đang hiển thị toàn bộ ván chưa xong và 1.000 ván đã xong gần nhất trong ')+s.historyTotal+tr(' ván. Các link replay cũ vẫn mở được trực tiếp.')):'')+fixturesTable(s,rows)):empty(tr('Chưa có giải đấu'),tr('Ban tổ chức sẽ mở giải để các đội đăng ký bot.'))}`;
}
function team(s) {
  const t=s.team;
  return `${head(t.name,tr('Thông tin đội đã đăng ký.'),link('change-password',tr('Đổi mật khẩu')))}<div class="real-two-col">${panel(tr('Thông tin đội'),l10n`<dl class="detail-list"><div><dt>Tên đội</dt><dd>${esc(t.name)}</dd></div><div><dt>Email đội trưởng</dt><dd>${esc(t.email)}</dd></div><div><dt>Điện thoại</dt><dd>${esc(t.phone||tr('Chưa cung cấp'))}</dd></div><div><dt>Tài khoản</dt><dd>${esc(s.user.username)}</dd></div></dl>${note(tr('Liên hệ ban tổ chức nếu cần thay đổi tên đội hoặc danh sách thành viên sau khi duyệt.'))}`)}${panel(tr('Thành viên'),table([tr('Họ và tên'),tr('Mã sinh viên')],t.members.map((m,i)=>`<tr><td>${esc(m.name)}${i===0?tr('<div class="muted">Đội trưởng</div>'):''}</td><td class="mono">${esc(m.student_id)}</td></tr>`)))}</div>`;
}
function job(s) {
  const j=s.job; if(!j)return empty(tr('Đang tải job…'));
  const r=j.report;
  return `${head((j.kind==='benchmark'?tr('Kiểm tra'):tr('Trận luyện tập'))+' · '+short(j.id),tr('Tiến độ và kết quả chạy bot.'),j.kind==='match'?link('arena/practice/'+j.id,tr('Mở bàn cờ'),'primary'):button(tr('Làm mới'),'refresh'))}<div id="job-status">${jobDetail(s)}</div>${r?panel(tr('Báo cáo đầy đủ'),l10n`<details><summary>Thời gian, cấu hình và thông tin bản build</summary><pre class="report-json">${esc(JSON.stringify(r,null,2))}</pre></details>`,button(tr('Tải JSON'),'download-report')):''}`;
}
export function jobDetail(s) {
  const j=s.job,r=j?.report;if(!j)return '';
  const groups=(r?.sandbox_metrics||[]).filter(x=>x?.cgroup).map(x=>x.cgroup);
  const maxMetric=items=>{const values=(items||[]).map(x=>x.wall_ms).filter(Number.isFinite);return values.length?metric(Math.max(...values)):'—';};
  const resources=groups.length?stats([['CPU container',metric(groups.reduce((sum,x)=>sum+x.cpu_usage_usec/1000,0)),'code',tr('Tổng CPU các container bot')],[tr('Bộ nhớ cao nhất'),(Math.max(...groups.map(x=>x.memory_peak_bytes))/1048576).toLocaleString(locale(),{maximumFractionDigits:2})+' MiB','grid',tr('Container bot dùng RAM cao nhất')],[tr('Khởi động'),maxMetric(r.startup),'clock',tr('Init → ready; không gồm tạo container')],[tr('Biên dịch'),maxMetric(r.artifacts),'clock',tr('Số đo lúc build artifact; có thể đã cache')]]):'';
  return `${panel(tr('Trạng thái'),`<div class="competition-summary">${badge(j.status)}${j.ruleset?badge('attention','Experimental · '+j.ruleset.definition.name):''}<span>${date(j.created_unix_ms)}</span><span>${timeLabel(j.profile)}</span><span>${j.ruleset?'Experimental · protocol v3':tr('OTT v2 tiêu chuẩn · protocol v2')}</span></div>${j.status==="queued"&&j.queue_position?note(tr("Đang chờ ở vị trí ")+j.queue_position+tr(" trong hàng đợi. Bấm Làm mới để xem vị trí mới.")):""}${j.eta?note(etaRange(j.eta)):""}${s.jobProgress?l10n`<p class="progress-label">${s.jobProgress.completed}/${s.jobProgress.total} mẫu hoàn tất</p>`:''}${j.error?l10n`<div class="form-error visible">${esc(j.error.code)} · Giai đoạn ${esc(({build:tr("Biên dịch"),startup:tr("Khởi động"),benchmark:tr("Kiểm tra"),turn:tr("Lượt đấu"),preflight:tr("Kiểm tra")})[j.error.stage]||j.error.stage||tr("Kiểm tra"))}: ${esc(j.error.detail)}</div>${jobErrorExplanation(j)?note(jobErrorExplanation(j)):""}${j.kind==='benchmark'?link('benchmark?submission='+j.submission_ids[0]+(j.competition_id?'&competition='+j.competition_id:'&'+timeQuery(j.profile))+(j.ruleset?'&ruleset='+j.ruleset.id:''),tr('Chọn luật & chạy lại'),'small'):""}`:''}${r?.result?note(resultLabel(r.result)):''}`)}${r?.fault||r?.startup_faults?.length?panel(tr('Chẩn đoán bot'),table([tr('Phe'),tr('Giai đoạn'),tr('Lỗi')],(r.startup_faults||[r.fault]).map(f=>`<tr><td>${sideName(f.side)}</td><td>${f.stage==='startup'?tr('Khởi động'):tr('Lượt ')+esc(f.turn_id||'—')}</td><td>${esc(resultReasons[f.code]||f.code)}<div class="muted">${esc(f.detail)}</div>${f.action?`<code>${esc(JSON.stringify(f.action))}</code>`:''}</td></tr>`))):''}${r?.turn_wall_ms?stats([[tr('Số mẫu'),r.turn_wall_ms.samples,'grid'],[tr('Trung vị'),metric(r.turn_wall_ms.median_ms),'clock'],['P95',metric(r.turn_wall_ms.p95_ms),'clock'],[tr('Tối đa'),metric(r.turn_wall_ms.max_ms),'clock']]):''}${resources}${groups.length?note(tr('CPU và bộ nhớ là số đo của cả container (gồm cả chương trình giám sát), không riêng bot. CPU từng lượt có trong báo cáo JSON.')):''}`;
}
const admin=adminTeams;
function guide(s) {
  const timing=[[tr('Tổng thời gian mỗi đội'),tr('Bullet: 1 phút · Đấu thường: 5 phút (mặc định). Chỉ trừ khi đến lượt, không cộng giây.')],[tr('Kiểm tra'),tr('72 mẫu độc lập, mỗi mẫu có giới hạn riêng 500 ms')],['Deadline',tr('Action phải được worker nhận đầy đủ trước deadline cứng')],[tr('Khoảng chờ'),tr('3 giây trước khi server đại diện đối thủ tuyên bố hết giờ; không nhận action muộn')],['Startup / build',tr('2 giây / 30 giây')],['Bot / build RAM',tr('256 MiB / 1.024 MiB; 1 CPU, một process/thread')],[tr('Kết thúc trận · v2'),tr('Lặp thế 3 lần, đạt 512 nước (bàn 9×9; bàn khác tăng theo số ô) hoặc quá 20 phút: hòa; server dừng / lỗi hạ tầng: không tính kết quả')]];
  const steps=[[tr('01 · Viết bot Python / C / C++'),tr('Giữ đúng một bot.py / bot.c / bot.cpp và file phụ cùng ngôn ngữ trong bot/ của repo private. Bot đọc observation và trả action qua JSON Lines trên stdin/stdout.')],[tr('02 · Test trên worker'),tr('Kiểm tra bot với 72 mẫu, mỗi mẫu tối đa 500 ms. Xem Đạt/Lỗi, median, P95, max và thông tin biên dịch trước khi đấu.')],[tr('03 · Chốt & thi đấu'),tr('Hub tự chốt theo giờ push GitHub tại hạn, lùi tối đa năm lần push nếu bản tại hạn Lỗi. BTC khóa danh sách; binary đã kiểm được giữ nguyên trong giải.')]];
  return head(tr('Tài liệu & thể lệ'),tr('Luật chơi, hướng dẫn viết bot và giới hạn vận hành.'),s.user&&s.user.role!=='admin'?button(tr('Tải starter OTTv2'),'starter','','primary'):s.user?link('home',tr('Về tổng quan')):link('login',tr('Đăng nhập để tải SDK'),'primary'))+
    githubGuide()+
    `<div class="real-card-grid">${steps.map(([title,text])=>panel(title,`<p>${text}</p>`)).join('')}</div>`+
    panel(tr('Hướng dẫn viết bot Python / C / C++'),l10n`<p>Mở từng mục để xem cách đóng gói, đọc input, trả nước đi và thử bot theo giao thức hiện tại.</p><div class="page-actions bot-guide-downloads"><a class="btn secondary" href="/_ui/bot-guide.md" download="OTTV2-BOT-GUIDE.md">Tải hướng dẫn ${icon('download')}</a><a class="btn secondary" href="/_ui/bot-example.cpp" download="bot.cpp">Tải mẫu C++ ${icon('download')}</a><a class="btn secondary" href="/_ui/ottv2-input.jsonl" download="ottv2-input.jsonl">Tải input mẫu ${icon('download')}</a></div>${renderBotGuide(s.botGuide)}`)+
    panel('Ruleset add-on',note(tr('Tính năng thử nghiệm do BTC bật. SDK v2 vẫn dành cho OTTv2 tiêu chuẩn; SDK mở rộng hỗ trợ năng lượng, vùng, cooldown, mẫu đi và Khiên.'))+(s.user?link('rulesets',tr('Thư viện luật & nước đi hợp lệ'),'small')+button(tr('Tải SDK v3 add-on'),'experimental-starter'):'')+l10n`<p><a href="/api/v1/experimental/guide">Hướng dẫn SDK v3, kỹ năng và timing</a></p>`)+
    panel(tr('Thời gian & tài nguyên'),table([tr('Giới hạn'),tr('Quy định')],timing.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`))+note(tr('Đồng hồ trình duyệt chỉ để hiển thị. Worker monotonic clock là nơi quyết định deadline. Python/Codon chưa được bật ở backend hiện tại.')))+
    panel(tr('Quy tắc vận hành bổ sung · v2'),note(policyLabel({adjudication:{id:'ottv2-match-v2'}}))+l10n`<p>Áp dụng cho luyện tập và giải mới. Giải cũ giữ thể lệ v1 đã ghim. Deadline cứng và quyền tuyên bố sau 3 giây giữ nguyên.</p>`)+
    panel(tr('Luật OTTv2'),l10n`<article class="rules-document" aria-label="Luật chơi OTTv2">${renderRules(s.rules||tr('Đang tải luật…'))}</article>`)+
    l10n`<div class="page-actions"><a class="btn secondary" href="/docs" target="_blank" rel="noopener">HTTP API quản lý nền tảng ${icon('arrow')}</a><a class="btn secondary" href="/api/v1/rules?lang=${language()}" download="OTTV2-RULES.md">Tải luật Markdown ${icon('download')}</a></div>`;
}

function limitsPage(){
  return head(tr('Giới hạn và cách báo lỗi'),tr('Thông tin dành cho người chơi.'))+
    panel(tr('Nộp và kiểm tra'),l10n`<p>Chỉ nộp qua thư mục bot/ trong repo GitHub private đã gắn với đội. Tối đa 30 bản mới mỗi giờ, 4 tác vụ riêng đang chạy và 4 tác vụ chờ mỗi đội. Bản mới có thể thay tác vụ đang chờ cùng mục đích; tác vụ đang chạy được giữ nguyên.</p><p>Kiểm tra có 72 mẫu, mỗi mẫu tối đa 500 ms. Luyện tập và thi đấu dùng quỹ thời gian ghi trên trang giải. Đang xếp hàng thì chưa có ETA; khi có đủ số liệu, thời gian còn lại hiện thành khoảng.</p>`)+
    panel(tr('Bản bot trong giải'),l10n`<p>Ladder dùng bản Đạt mới nhất tại lúc đợt bắt đầu. Push trong lúc đấu được kiểm tra ngay và tham gia từ đợt sau. Sau hạn, bot chính thức được khóa theo SHA; không dùng ngày commit tự khai.</p><p>Replay luyện tập và ladder giữ 50 ván gần nhất mỗi đội; mọi kết quả và replay chính thức được giữ. Hub giữ cache 3 nguồn và 2 binary theo vai trò, có thể tải lại nguồn cũ từ GitHub nếu còn quyền đọc.</p>`)+
    panel(tr('Báo lỗi cho BTC'),l10n`<p>Gửi qua kênh liên lạc BTC đã công bố cho lớp: mã đội, link tác vụ hoặc ván, SHA, thời điểm xảy ra và mô tả ngắn các bước tái hiện. Không gửi mật khẩu, token GitHub, token máy chấm hay mã xác minh.</p><p>Nếu nghi có lỗi lộ bài hoặc gian lận, báo riêng BTC. Tên bot trùng hoặc mã nguồn giống bot mẫu không tự động bị coi là gian lận.</p>`);
}

export function page(s) {
  if(s.route==='finals'&&!s.loading&&!s.error){const content=finalsPage(s);return s.query?.get('chieu')==='1'?`<main id="main" class="finals-projection">${content}</main>`:shell(s,content);}
  if(['register','recover','verify-email','set-password'].includes(s.route))return personalAuthPage(s);
  if(s.route==='guest-register')return authPage({...s,route:'register'});
  if(s.route==='guest-recover')return authPage({...s,route:'recover'});
  if(['login','register','recover','change-password'].includes(s.route)) return authPage(s);
  let content=s.loading?empty(tr('Đang tải dữ liệu…')):s.error?`${head(tr('Chưa tải được trang.'))}<div class="form-error visible">${esc(s.error)}</div>${button(tr('Thử lại'),'refresh')}`:({rulesets:x=>x.ids?.[0]?addonDetailPage(x):addonPage(x),graders:gradersPage,email:emailPage,users:peopleAdminPage,matching:matchingPage,home,submissions,benchmark,practice,competitions,standings,limits:limitsPage,announcements:announcementsPage,queue:queuePage,team:x=>x.personal?accountTeamPage(x):team(x),admin,operations:x=>adminOperations(x)+sampleAdmin(x),guide,jobs:job,live:x=>schedule(x,true),schedule:x=>schedule(x,false),audit:x=>head(tr('Nhật ký quản trị.'),tr('Theo dõi thao tác; không ghi mật khẩu hoặc source.'))+panel(tr('Nhật ký'),table([tr('Người thực hiện'),tr('Thao tác'),tr('Đối tượng'),tr('Thời gian')],x.audit.map(a=>`<tr><td class="mono">${esc(a.actor)}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.target)}</td><td>${date(a.created_ms)}</td></tr>`)))}[s.route]?.(s)||'');
  return shell(s,content);
}
